Definition is_havoc : ltac2:(zQ "30!jt2!io1!m3>2lo$0>2hi$0>1t$2@1$1$0") := ltac2:(zQ "c0!jt2!m3!ok9!hs7!io1!h9!soe!sq3!mvd!hu6!hmhd!hmi4\2lo$0\2hi$0\1t$1M1\1t$1@1$4$0^1\1z$5@1$2$0\1v$0M3\0$3@1$4$0@2$9@2$a^4^1@2$b^1^3@2$8$0^1@1$2$0\2op$6\1a$1\1b$1@1$2$0\2op$6\1a$1\1b$1@1$2$0\2op$7\1a$1\1b$1@1$2$0\2op$7\1a$1\1b$1@1$2$0\2sx$3\3lo0$0\1n$0\1e$1@1$2$0\2sx$3\1k$0\1i$5\1n$0@1$2$0").

Fixpoint henv (lo hi : nat) (E : env) (rs ts : list expr) : env :=
  match rs, ts with
  | r :: rs', t :: ts' =>
      let E1 := henv lo hi E rs' ts' in
      match is_havoc lo hi t with Some v => upd E1 v (edenot E r) | None => E1 end
  | _, _ => E
  end.

